for(const [suffix,label]of [['App','application SP'],['Broker','Realm A acting as the broker SP']]){
  const app=suffix==='App',sp=app?'urn:example:app:sp':'urn:example:realm-a:broker:sp',acs=app?'https://app.example.test/saml/acs':'https://idp1.example.test/realms/realm-a/broker/saml-partner/endpoint';
  Object.assign(SAML_ATTRIBUTES,{
    ['samlSpEntity'+suffix]:samlAttr('entityID / AuthnRequest.Issuer ('+label+')','The registered SAML identity of the '+label+'.','Registered in SP metadata and IdP client configuration.','Selects the SP registration. In Keycloak this matches the SAML Client ID; no OAuth client_id parameter is sent.',sp),
    ['samlAcs'+suffix]:samlAttr('AssertionConsumerServiceURL ('+label+')','The registered HTTPS assertion-consumer endpoint.','Configured in SP metadata and approved by the IdP.','The SP requests/receives the browser SAML POST here; it is distinct from the SP entityID.',acs),
    ['samlRequestId'+suffix]:samlAttr('AuthnRequest/@ID ('+label+')','The unique identifier of this SP-initiated request.','Generated by the requesting SP and stored with its pending transaction.','The recipient later matches response and bearer confirmation InResponseTo to this value.',app?'_app_req_7f81':'_broker_req_94ac'),
    ['samlResponseId'+suffix]:samlAttr('Response/@ID ('+label+')','The unique ID of the IdP response.','Generated by the IdP.','Identifies the protocol response and its XML signature reference.',app?'_app_resp_1c52':'_broker_resp_2d63'),
    ['samlAssertionId'+suffix]:samlAttr('Assertion/@ID ('+label+')','The unique identifier of this assertion.','Generated by the issuing IdP.','Used by XML signature references and recipient replay protection.',app?'_app_assert_3e74':'_broker_assert_4f85'),
    ['samlRelayState'+suffix]:samlAttr('RelayState ('+label+')','An opaque binding value associated with SP application/transaction state.','In SP initiation, generated and stored by the requesting SP.','Returned unchanged and validated separately; keep it at most 80 bytes. POST XML signatures do not cover this separate form value.',app?'rs_app_7f81':'rs_broker_94ac','SAML 2.0 Bindings RelayState',samlBindingsUrl),
    ['samlInResponseTo'+suffix]:samlAttr('InResponseTo ('+label+')','Request correlation in Response and bearer SubjectConfirmationData.','Copied by the IdP from the SP’s AuthnRequest.ID.','The SP checks it against its pending request. It is absent in an unsolicited IdP-initiated app response.',app?'_app_req_7f81':'_broker_req_94ac'),
    ['samlNameId'+suffix]:samlAttr('NameID ('+label+')','The subject identifier presented to this SP.','The IdP derives it according to configured NameID format and mapping.','Identifies the trusted subject together with issuer/format. It is not automatically an OIDC sub.',app?'a-persistent-204':'b-persistent-913'),
    ['samlAudience'+suffix]:samlAttr('Audience ('+label+')','The permitted SP entityID in assertion AudienceRestriction.','Set by the IdP from the registered SP.','The receiver requires its own entityID; an audience is not the ACS URL.',sp),
    ['samlRecipient'+suffix]:samlAttr('Recipient ('+label+')','The ACS address in bearer SubjectConfirmationData.','Set by the IdP from the permitted response endpoint.','The recipient checks the value against its actual ACS URL.',acs),
    ['samlSessionIndex'+suffix]:samlAttr('SessionIndex ('+label+')','The IdP session identifier in AuthnStatement.','Generated/selected by the IdP for the authenticated session.','Can support SAML session management/logout; logout is outside this animation.',app?'saml_session_A_41':'saml_session_B_73'),
    ['samlAuthnContext'+suffix]:samlAttr('AuthnContextClassRef ('+label+')','The authentication-context class asserted under an agreed policy.','Emitted by the IdP only with configured mapping/enforcement semantics.','Describes the accepted authentication context; a URI alone is not an automatic MFA guarantee.','urn:example:authn-context:webauthn-user-verified'),
    ['samlEncryptionCertificate'+suffix]:samlAttr('SP encryption certificate ('+label+')','The SP’s public encryption key/certificate registered for encrypted assertions.','Published in trusted SP metadata or explicitly registered with the IdP.','The IdP uses this public key to wrap the temporary content-encryption key.','Public recipient X.509 certificate; not a private key','SAML metadata / XML Encryption',samlXmlEncUrl),
    ['samlDecryptKey'+suffix]:samlAttr('SP decryption key (private; '+label+')','The private key corresponding to the SP encryption certificate.','Provisioned and retained only by the receiving SP backend.','Unwraps the encrypted content key locally. It is never sent through the browser.','Recipient-only private decryption key; never transmitted','XML Encryption 1.1',samlXmlEncUrl),
  });
}
for(const [suffix,entity,actor]of [['App','urn:example:app:sp','application SP'],['A',EXAMPLE.issuerA,'Realm A'],['B',EXAMPLE.issuerB,'upstream IdP']]){
  Object.assign(SAML_ATTRIBUTES,{
    ['samlSigningKey'+suffix]:samlAttr('SAML signing key (private; '+actor+')','The sender’s configured private XML/query signing key.','Retained in the '+actor+' backend/key provider.','Signs protocol messages locally. Receivers verify with trusted public metadata keys.','Private signing key; never transmitted','SAML signing policy / XML Signature','https://www.w3.org/TR/xmldsig-core1/'),
    ['samlSigningCertificate'+suffix]:samlAttr('SAML signing certificate ('+actor+')','The trusted public key/certificate for this sender.','Obtained from authenticated configuration/metadata exchange.','Used to verify the expected signed element. An untrusted certificate inside ds:KeyInfo does not establish trust.','Trusted public X.509 signing certificate','SAML metadata / XML Signature','https://www.w3.org/TR/xmldsig-core1/'),
  });
  if(suffix!=='App')SAML_ATTRIBUTES['samlIdpEntity'+suffix]=samlAttr('Issuer / entityID ('+actor+')','The configured SAML identity of this IdP.','Published in trusted IdP metadata and configured at the SP.','The SP checks the exact expected issuer, independently of browser origin or OIDC issuer conventions.',entity);
}
SAML_ATTRIBUTES.samlSsoA=samlAttr('SingleSignOnService Location (Realm A)','Realm A’s SAML SSO endpoint from metadata.','Configured/published by Realm A.','An AuthnRequest Destination points here.',EXAMPLE.issuerA+'/protocol/saml','SAML 2.0 Metadata','https://docs.oasis-open.org/security/saml/v2.0/saml-metadata-2.0-os.pdf');
SAML_ATTRIBUTES.samlSsoB=samlAttr('SingleSignOnService Location (upstream IdP)','The upstream SAML SSO endpoint.','Published in trusted provider metadata.','Realm A sends its broker AuthnRequest here.',EXAMPLE.issuerB+'/protocol/saml','SAML 2.0 Metadata','https://docs.oasis-open.org/security/saml/v2.0/saml-metadata-2.0-os.pdf');

export const SAML_TOPIC_IDS=Object.freeze(Object.keys(SAML_ATTRIBUTES));
