  const xml='<samlp:AuthnRequest ID="'+v(h.requestId)+'" Version="2.0" IssueInstant="'+samlClock+'" Destination="'+v(h.ssoId)+'" AssertionConsumerServiceURL="'+v(h.acsId)+'" ProtocolBinding="'+samlPostBinding+'"><saml:Issuer>'+v(h.entityId)+'</saml:Issuer></samlp:AuthnRequest>';
