  const redirect=h.config.binding==='redirect';
  const bindingOps=[...samlOp([h.spSigningKey],'use',h.sp,'The configured SP private signing key stays on this server.')];
  if(redirect)bindingOps.push(...samlOp(['samlRequest'],'derive',h.sp,'Serializes XML, applies raw RFC 1951 DEFLATE, Base64 and URL encoding.'),...samlOp(['samlSigAlg','samlRedirectSignature'],'derive',h.sp,'Signs the exact original URL-encoded SAMLRequest&RelayState&SigAlg string, in that order.'));
  else bindingOps.push(...samlOp(['samlXmlSignature'],'derive',h.sp,'Adds an enveloped ds:Signature to the AuthnRequest XML; the separate RelayState form field is not signed by this XML signature.'),...samlOp(['samlRequest'],'derive',h.sp,'Base64-encodes the signed XML for the HTTP-POST form; no DEFLATE.'));
  const encoded=redirect?'URL_ENCODE(BASE64(RAW_DEFLATE(AuthnRequest XML)))':'BASE64(signed AuthnRequest XML)';
  const wireIds=['samlRequest',h.relayId,...(redirect?['samlSigAlg','samlRedirectSignature']:['samlXmlSignature'])],nestedIds=['samlAuthnRequest',...requestMembers],allWireIds=[...wireIds,...nestedIds];
  const bindingPayload=redirect?[samlPayload('HTTP','302 Found'),samlPayload('Location',v(h.ssoId)+'?SAMLRequest='+encoded+'&RelayState='+v(h.relayId)+'&SigAlg=URL_ENCODE('+samlRsaSha256+')&Signature=URL_ENCODE(BASE64(signature bytes))'),samlPayload('Signed query','SAMLRequest=<original encoded value>&RelayState=<original encoded value>&SigAlg=<original encoded URI>')]:[samlPayload('HTTP','200 HTML auto-submit form'),samlPayload('Form action',v(h.ssoId)),samlPayload('SAMLRequest',encoded),samlPayload('RelayState',v(h.relayId))];
